(()=>{const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];let seq=0;const roles=['Beneficial owner','Controller','Director / governing officer','Partner / member','Founder','Trustee / council member','Beneficiary'];
function enhance(){all('.ubo').forEach(row=>{if(row.dataset.personReady)return;row.dataset.personReady='yes';row.dataset.recordId='person-'+(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+(++seq));const label=document.createElement('label');label.className='field';label.innerHTML='<span>Full name of this person</span><input class="ubo-name" required autocomplete="off" placeholder="Name as shown on identity documents">';row.querySelector('.ubo-grid').before(label);const fieldset=document.createElement('fieldset');fieldset.className='person-roles';const legend=document.createElement('legend');legend.textContent='Relevant roles — select all that apply';const box=document.createElement('div');box.className='checks';roles.forEach(role=>{const l=document.createElement('label'),e=document.createElement('input');e.type='checkbox';e.value=role;e.checked=role==='Beneficial owner';l.append(e,role);box.append(l);});fieldset.append(legend,box);label.after(fieldset);const old=row.querySelector('.residence'),select=document.createElement('select');select.className='residence';select.required=true;select.add(new Option('Select country',''));countryNames.forEach(c=>select.add(new Option(c,c)));select.value=old.value;old.replaceWith(select);row.querySelector('.pct').min='0';row.querySelector('.pct').required=false;row.querySelector('.pct').closest('label').querySelector('span').textContent='Ownership % (if applicable)';row.querySelector('h3').textContent='Person '+(all('.ubo').indexOf(row)+1);});}
const add=addUBO;addUBO=function(...args){add(...args);enhance();};q('#add-ubo').onclick=()=>addUBO();q('#add-ubo').textContent='+ Add person';enhance();
const oldTotals=totals;totals=function(){oldTotals();all('.ubo').forEach((r,i)=>r.querySelector('h3').textContent='Person '+(i+1));q('#ubo-count').textContent=all('.ubo').length+' people identified';q('#ubo-remaining').textContent='Percentages describe declared ownership only';q('#remaining-explanation').hidden=true;};totals();
window.ApplicantRecords=window.ApplicantRecords||{};
ApplicantRecords.persons=()=>all('.ubo').map(row=>({id:row.dataset.recordId,fullName:row.querySelector('.ubo-name').value.trim(),name:row.querySelector('.ubo-name').value.trim(),sharePercentage:row.querySelector('.pct').value===''?null:Number(row.querySelector('.pct').value),percentage:row.querySelector('.pct').value,controlRoles:[...row.querySelectorAll('.person-roles input:checked')].map(e=>e.value),nationalities:row.querySelector('.nationality-picker').__values?.()||row.querySelector('.nationality').value.split(', ').filter(Boolean),residence:row.querySelector('.residence').value}));
ApplicantRecords.ownership=()=>({entityType:q('#entity-type').value,clarification:q('#ownership-clarification').value.trim(),listing:{claimed:q('#plc-listed')?.value==='Yes',exchange:q('#plc-exchange')?.value||'',disclosure:q('#plc-disclosure')?.value||'',verified:false,status:q('#plc-listed')?.value==='Yes'?'Verification pending':'Not claimed'}});
ownershipReady=function(){const persons=ApplicantRecords.persons();if(!persons.length){note('Identify at least one relevant owner, controller or governing person. No ownership percentage is required for a control-only person.');return false;}for(let i=0;i<persons.length;i++){const p=persons[i],r=all('.ubo')[i];if(!p.name||!p.controlRoles.length||!p.nationalities.length||!countryNames.includes(p.residence)){note('Complete the full name, role, nationalities and country of residence for person '+(i+1)+'.');r.querySelector('.ubo-name').focus();return false;}if(p.sharePercentage!==null&&(!Number.isFinite(p.sharePercentage)||p.sharePercentage<0||p.sharePercentage>100)){note('Enter an ownership percentage between 0 and 100, or leave it blank where it does not apply.');return false;}}if(persons.reduce((n,p)=>n+(p.sharePercentage||0),0)>100.0001){note('Declared ownership percentages cannot total more than 100%.');return false;}if(q('#entity-type').value.startsWith('Public limited')){if(!q('#plc-listed').value){note('Indicate whether the company is listed.');return false;}if(q('#plc-listed').value==='Yes'&&(!q('#plc-exchange').value.trim()||!q('#plc-disclosure').value.trim()||!q('#plc-disclosure').checkValidity())){note('Provide the exchange/listing identifier and public disclosure URL. Listing verification remains pending.');return false;}}if(q('#corporate').value==='Yes'&&[...q('#entity-list').querySelectorAll('input')].some(e=>!e.value.trim())){note('Complete the registered name and incorporation jurisdiction of each shareholder entity.');return false;}return true;};
const refresh=refreshFlow;refreshFlow=function(){refresh();q('#ubos').closest('section').hidden=false;const actions=q('[data-screen="4"] .actions');if(actions)q('[data-screen="4"]').append(actions);};q('#entity-type').addEventListener('change',()=>refreshFlow());})();

